-- Company RLS fence for billing module (ADR-0008)
-- Generated by metaphor-schema. Requires the app to connect as a
-- non-superuser role; migrations/seeders run as the owner and bypass.

-- Migration: company row-level-security fence for billing.payment_schedules
-- Generated by metaphor-schema (ADR-0008). company_id is scoped per request
-- via `set_config('app.company_id', <uuid>, true)`; an unset var sees zero rows.

ALTER TABLE billing.payment_schedules ENABLE ROW LEVEL SECURITY;
ALTER TABLE billing.payment_schedules FORCE  ROW LEVEL SECURITY;
DROP POLICY IF EXISTS payment_schedules_company_isolation ON billing.payment_schedules;
CREATE POLICY payment_schedules_company_isolation ON billing.payment_schedules
    FOR ALL
    USING      (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid)
    WITH CHECK (company_id = NULLIF(current_setting('app.company_id', true), '')::uuid);

